//! Help texts and messages in every language the app offers, written for this app after the
//! original's help topics (its own help files aren't copied).

use crate::i18n::Lang;

/// Help topics: the main screen and one per test pattern (some patterns have two).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Topic {
    Main = 0,
    Geometry,
    Brightness,
    Luminosity,
    HighVoltage,
    Colors,
    ColorSquare,
    Convergence1,
    Convergence3,
    Focus,
    Resolution,
    Moire,
    Readability,
    Jitter,
}

pub struct Texts {
    /// (title, body) per topic, in the order of `Topic`.
    pub topics: [(&'static str, &'static str); 14],
    /// Sample text for the readability pattern.
    pub reading: &'static str,
    pub sound_failed: &'static str,
    pub display_failed: &'static str,
    /// `{url}` is replaced by the address.
    pub web_failed: &'static str,
    pub choose_language: &'static str,
    pub asked_once: &'static str,
    pub hint_next: &'static str,
    pub hint_prev: &'static str,
    pub hint_back: &'static str,
}

impl Texts {
    pub fn topic(&self, t: Topic) -> (&'static str, &'static str) {
        self.topics[t as usize]
    }
}

pub fn texts(lang: Lang) -> &'static Texts {
    match lang {
        Lang::English => &EN,
        Lang::Finnish => &FI,
        Lang::German => &DE,
        Lang::French => &FR,
        Lang::Spanish => &ES,
        Lang::Dutch => &NL,
        Lang::Swedish => &SV,
        Lang::Norwegian => &NO,
        Lang::Italian => &IT,
        Lang::Thai => &TH,
    }
}

